def glob_to_regex(pattern, case_sensitive=True):
    """Convert a glob pattern to a regex pattern, handling ** and character classes."""
    # Handle special ripgrep glob patterns
    # Convert glob to regex
    result = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '**':
            result.append('.*')
            i += 2
            continue
        elif pattern[i:i+2] == '**':
            result.append('.*')
            i += 2
            continue
        elif c == '*':
            if i + 1 < len(pattern) and pattern[i+1] == '*':
                result.append('.*')
                i += 2
                continue
            result.append('[^/]*')
        elif c == '?':
            result.append('[^/]')
        elif c == '[':
            # Find the matching ]
            j = i + 1
            bracket = '['
            if j < len(pattern) and pattern[j] in ('!', '^'):
                bracket += '^'
                j += 1
            elif j < len(pattern) and pattern[j] == ']':
                bracket += ']'
                j += 1
            while j < len(pattern) and pattern[j] != ']':
                bracket += re.escape(pattern[j]) if pattern[j] not in '-\\' else pattern[j]
                j += 1
            bracket += ']'
            result.append(bracket)
            i = j + 1
            continue
        elif c == '{':
            # Handle {a,b,c} alternation
            j = i + 1
            depth = 1
            while j < len(pattern) and depth > 0:
                if pattern[j] == '{':
                    depth += 1
                elif pattern[j] == '}':
                    depth -= 1
                j += 1
            inner = pattern[i+1:j-1]
            alts = inner.split(',')
            result.append('(?:' + '|'.join(re.escape(a) for a in alts) + ')')
            i = j
            continue
        elif c == '\\':
            if i + 1 < len(pattern):
                result.append(re.escape(pattern[i+1]))
                i += 2
                continue
        else:
            result.append(re.escape(c))
        i += 1

    flags = 0 if case_sensitive else re.IGNORECASE
    return re.compile('(?:' + ''.join(result) + ')$', flags)


def matches_glob(name, pattern, case_sensitive=True):
    """Check if a filename matches a glob pattern."""
    if case_sensitive:
        return fnmatch.fnmatch(name, pattern)
    else:
        return fnmatch.fnmatch(name.lower(), pattern.lower())


def matches_any_glob(path_str, globs, case_sensitive=True):
    """Check if a path matches any of the given glob patterns."""
    # Normalize path
    path_str = path_str.replace('\\', '/')
    basename = os.path.basename(path_str)

    for pattern in globs:
        # Negate patterns start with !
        if pattern.startswith('!'):
            continue
        # If pattern contains /, match against full path
        if '/' in pattern.lstrip('/'):
            if _fnmatch_path(path_str, pattern, case_sensitive):
                return True
        else:
            if case_sensitive:
                if fnmatch.fnmatch(basename, pattern):
                    return True
            else:
                if fnmatch.fnmatch(basename.lower(), pattern.lower()):
                    return True
    return False


def _fnmatch_path(path, pattern, case_sensitive=True):
    """Match path against pattern, handling ** properly."""
    # Normalize
    path = path.replace('\\', '/')
    pattern = pattern.replace('\\', '/')

    # Convert glob pattern to regex
    def to_regex(p):
        result = []
        i = 0
        while i < len(p):
            if p[i:i+2] == '**':
                result.append('.*')
                i += 2
                if i < len(p) and p[i] == '/':
                    i += 1
            elif p[i] == '*':
                result.append('[^/]*')
                i += 1
            elif p[i] == '?':
                result.append('[^/]')
                i += 1
            elif p[i] == '[':
                j = i + 1
                cls = '['
                if j < len(p) and p[j] in ('!', '^'):
                    cls += '^'
                    j += 1
                while j < len(p) and p[j] != ']':
                    cls += re.escape(p[j]) if p[j] not in '-' else '-'
                    j += 1
                cls += ']'
                result.append(cls)
                i = j + 1
            else:
                result.append(re.escape(p[i]))
                i += 1
        return ''.join(result)

    rx_str = to_regex(pattern)
    flags = 0 if case_sensitive else re.IGNORECASE
    try:
        rx = re.compile(rx_str + '$', flags)
        # Try matching full path and also just the basename
        if rx.search(path):
            return True
        # If pattern doesn't start with /, try matching from anywhere
        if not pattern.startswith('/'):
            # Try matching against any suffix
            parts = path.split('/')
            for i in range(len(parts)):
                subpath = '/'.join(parts[i:])
                if rx.match(subpath + '') or rx.search(subpath):
                    try:
                        if re.fullmatch(rx_str, subpath, flags):
                            return True
                    except:
                        pass
        return False
    except:
        return fnmatch.fnmatch(path, pattern)


