class IgnoreRules:
    """Handles .gitignore, .ignore, .rgignore rules."""

    def __init__(self, root_path=None, require_git=True, no_ignore=False,
                 no_ignore_dot=False, no_ignore_vcs=False, no_ignore_global=False,
                 no_ignore_parent=False, extra_ignore_files=None, 
                 ignore_file_case_insensitive=False):
        self.require_git = require_git
        self.no_ignore = no_ignore
        self.no_ignore_dot = no_ignore_dot
        self.no_ignore_vcs = no_ignore_vcs
        self.no_ignore_global = no_ignore_global
        self.no_ignore_parent = no_ignore_parent
        self.ignore_file_case_insensitive = ignore_file_case_insensitive

        # Cache of ignore rules per directory
        self._rules_cache = {}
        self._git_roots = set()

        # Extra ignore files
        self.extra_ignore_files = extra_ignore_files or []
        self._extra_rules = []
        for f in self.extra_ignore_files:
            try:
                rules = self._load_ignore_file(f)
                self._extra_rules.extend(rules)
            except:
                pass

    def _find_git_root(self, path):
        """Find the git root for the given path."""
        current = Path(path).resolve()
        while current != current.parent:
            if (current / '.git').exists():
                return str(current)
            current = current.parent
        return None

    def _load_ignore_file(self, filepath):
        """Load rules from an ignore file."""
        rules = []
        try:
            with open(filepath, 'r', errors='replace') as f:
                for line in f:
                    line = line.rstrip('\n').rstrip('\r')
                    if line and not line.startswith('#'):
                        rules.append(line)
        except:
            pass
        return rules

    def _get_dir_rules(self, dirpath):
        """Get ignore rules for a specific directory."""
        dirpath = str(Path(dirpath).resolve())
        if dirpath in self._rules_cache:
            return self._rules_cache[dirpath]

        rules = []  # list of (pattern, negate, base_dir)

        if not self.no_ignore:
            # Load .rgignore (highest priority after .git)
            if not self.no_ignore_dot:
                for fname in ['.rgignore', '.ignore']:
                    fpath = os.path.join(dirpath, fname)
                    if os.path.exists(fpath):
                        for pattern in self._load_ignore_file(fpath):
                            negate = pattern.startswith('!')
                            if negate:
                                pattern = pattern[1:]
                            rules.append((pattern, negate, dirpath))

            # Load .gitignore if in/near git repo
            if not self.no_ignore_vcs:
                git_root = self._find_git_root(dirpath)
                if git_root or not self.require_git:
                    gitignore = os.path.join(dirpath, '.gitignore')
                    if os.path.exists(gitignore):
                        for pattern in self._load_ignore_file(gitignore):
                            negate = pattern.startswith('!')
                            if negate:
                                pattern = pattern[1:]
                            rules.append((pattern, negate, dirpath))

        self._rules_cache[dirpath] = rules
        return rules

    def _pattern_matches(self, pattern, path, base_dir):
        """Check if a pattern matches a path relative to base_dir."""
