    def __init__(self, patterns, options):
        self.patterns = patterns
        self.opts = options
        self.compiled_re = None
        self.error = None

        # Compile the regex
        self._compile()

    def _compile(self):
        # Check for unsupported features first
        for p in self.patterns:
            if not self.opts.get('fixed_strings', False):
                # Check lookahead/lookbehind
                if self._has_lookaround(p):
                    wrapped = f"(?:{self._get_combined_pattern()})"
                    self.error = self._make_lookaround_error(p, wrapped)
                    return
                # Check backreferences
                if re.search(r'\\[1-9]', p):
                    wrapped = f"(?:{self._get_combined_pattern()})"
                    self.error = self._make_backref_error(p, wrapped)
                    return

        result = compile_pattern(self.patterns, self.opts)
        self.compiled_re, self.error = result

    def _has_lookaround(self, pattern):
        """Check if pattern contains lookahead or lookbehind."""
        # Simple check for (?= (?! (?<= (?<!
        i = 0
        while i < len(pattern):
            if pattern[i] == '\\':
                i += 2
                continue
            if pattern[i] == '(' and i + 1 < len(pattern) and pattern[i+1] == '?':
                if i + 2 < len(pattern):
                    ch = pattern[i+2]
                    if ch in ('=', '!'):
                        return True
                    if ch == '<' and i + 3 < len(pattern) and pattern[i+3] in ('=', '!'):
                        return True
            i += 1
        return False

    def _get_combined_pattern(self):
        if self.opts.get('fixed_strings', False):
            parts = [re.escape(p) for p in self.patterns]
        else:
            parts = self.patterns
        return '|'.join('(?:' + p + ')' for p in parts)

    def _make_lookaround_error(self, pattern, wrapped):
        # Find the position of the lookaround
        m = re.search(r'\(\?(?:[=!]|<[=!])', pattern)
        if m:
            # Find in wrapped pattern
            pos_in_wrapped = wrapped.find(m.group(), 3)
            if pos_in_wrapped < 0:
                pos_in_wrapped = 3
            spaces = ' ' * (4 + pos_in_wrapped)
            carets = '^' * len(m.group())
            return f"rg: regex parse error:\n    {wrapped}\n{spaces}{carets}\nerror: look-around, including look-ahead and look-behind, is not supported"
        return f"rg: regex parse error:\n    {wrapped}\nerror: look-around, including look-ahead and look-behind, is not supported"

    def _make_backref_error(self, pattern, wrapped):
        m = re.search(r'\\([1-9])', pattern)
        if m:
            pos_in_wrapped = wrapped.find(m.group(), 3)
            if pos_in_wrapped < 0:
                pos_in_wrapped = 3
            spaces = ' ' * (4 + pos_in_wrapped)
            carets = '^^'
            return f"rg: regex parse error:\n    {wrapped}\n{spaces}{carets}\nerror: backreferences are not supported"
        return f"rg: regex parse error:\n    {wrapped}\nerror: backreferences are not supported"

    def search_lines(self, lines, file_path, start_offset=0):
        """Search through lines and yield SearchResult objects."""
        if self.error:
            return

        if self.opts.get('multiline', False):
            yield from self._search_multiline(lines, file_path, start_offset)
            return

        invert = self.opts.get('invert_match', False)
        max_count = self.opts.get('max_count', None)
        stop_on_nonmatch = self.opts.get('stop_on_nonmatch', False)
        null_data = self.opts.get('null_data', False)

        match_count = 0
        byte_offset = start_offset

        for line_num, line in enumerate(lines, 1):
            # Track byte offset
            if null_data:
                line_bytes = line.encode('utf-8', errors='replace') + b'\x00'
            else:
                line_bytes = line.encode('utf-8', errors='replace') + b'\n'

            # Check for match
            matches = list(self.compiled_re.finditer(line))
            has_match = bool(matches)

            if invert:
                if not has_match:
                    yield SearchResult(file_path, line_num, line, byte_offset, [])
                    if stop_on_nonmatch:
                        byte_offset += len(line_bytes)
                        continue
                elif stop_on_nonmatch:
                    byte_offset += len(line_bytes)
                    break
            else:
                if has_match:
                    match_spans = [(m.start(), m.end()) for m in matches]
                    yield SearchResult(file_path, line_num, line, byte_offset, match_spans)
                    match_count += 1
                    if max_count is not None and match_count >= max_count:
                        byte_offset += len(line_bytes)
                        break
                elif stop_on_nonmatch:
                    byte_offset += len(line_bytes)
                    break

            byte_offset += len(line_bytes)

    def _search_multiline(self, lines, file_path, start_offset=0):
        """Search in multiline mode."""
        # Join all lines and search
        content = '\n'.join(lines)
        if not content.endswith('\n') and lines:
            pass  # Already joined without trailing newline

        invert = self.opts.get('invert_match', False)
        max_count = self.opts.get('max_count', None)

        matches = list(self.compiled_re.finditer(content))

        if invert:
            # For invert in multiline mode, output non-matching lines
            for line_num, line in enumerate(lines, 1):
                if not self.compiled_re.search(line):
                    yield SearchResult(file_path, line_num, line, 0, [])
            return

        if not matches:
            return

        # For each match, find which lines it spans
        line_starts = [0]
        for line in lines[:-1]:
            line_starts.append(line_starts[-1] + len(line) + 1)

        yielded = set()
        match_count = 0

        for m in matches:
            # Find start line
            start_line_idx = 0
            for i, ls in enumerate(line_starts):
                if ls <= m.start():
                    start_line_idx = i

            end_line_idx = start_line_idx
            for i in range(start_line_idx, len(line_starts)):
                if i + 1 < len(line_starts):
                    if line_starts[i+1] > m.end():
                        end_line_idx = i
                        break
                else:
                    end_line_idx = i

            # Yield each matched line
            for li in range(start_line_idx, end_line_idx + 1):
                if li not in yielded:
                    yielded.add(li)
                    line = lines[li]
                    # Find matches within this line
                    line_match_spans = [(mm.start(), mm.end()) for mm in self.compiled_re.finditer(line)]
                    yield SearchResult(file_path, li + 1, line, line_starts[li] + start_offset, line_match_spans)
                    match_count += 1
                    if max_count is not None and match_count >= max_count:
                        return


