def apply_replacement(line, matches, replacement, compiled_re):
    """Apply a replacement string to a line."""
    # ripgrep uses $0, $1, $2 etc for groups, and ${name} for named groups
    # Convert to Python format

    def replace_func(m):
        result = []
        i = 0
        repl = replacement
        while i < len(repl):
            if repl[i] == '$':
                if i + 1 < len(repl):
                    if repl[i+1] == '{':
                        # ${name} or ${N}
                        j = repl.find('}', i + 2)
                        if j >= 0:
                            name = repl[i+2:j]
                            try:
                                if name.isdigit():
                                    idx = int(name)
                                    if idx == 0:
                                        result.append(m.group(0))
                                    else:
                                        g = m.group(idx)
                                        result.append(g if g is not None else '')
                                else:
                                    g = m.group(name)
                                    result.append(g if g is not None else '')
                            except (IndexError, error):
                                result.append('')
                            i = j + 1
                            continue
                    elif repl[i+1].isdigit():
                        idx = int(repl[i+1])
                        if idx == 0:
                            result.append(m.group(0))
                        else:
                            try:
                                g = m.group(idx)
                                result.append(g if g is not None else '')
                            except IndexError:
                                result.append('')
                        i += 2
                        continue
                    elif repl[i+1] == '$':
                        result.append('$')
                        i += 2
                        continue
                result.append(repl[i])
                i += 1
            else:
                result.append(repl[i])
                i += 1
        return ''.join(result)

    return compiled_re.sub(replace_func, line)


def format_output_line(result, opts, use_color, is_context=False):
    """Format a single result line for output."""
    output = io.StringIO()

    file_path = result.file_path
    line_num = result.line_number
    line = result.line_content
    byte_offset = result.byte_offset
    matches = result.matches

    show_filename = opts.get('show_filename', False)
    show_line_number = opts.get('line_number', False)
    show_column = opts.get('column', False)
    show_byte_offset = opts.get('byte_offset', False)
    heading = opts.get('heading', False)
    only_matching = opts.get('only_matching', False)
    replacement = opts.get('replace', None)
    trim = opts.get('trim', False)
    null_sep = opts.get('null', False)  # -0 flag

    field_match_sep = opts.get('field_match_separator', ':')
    field_context_sep = opts.get('field_context_separator', '-')

    sep = field_context_sep if is_context else field_match_sep

    # Build prefix parts
    prefix_parts = []

    if show_filename and not heading:
        path_str = opts.get('path_separator', None)
        if path_str:
            fp = file_path.replace('/', path_str).replace('\\', path_str) if path_str != '/' else file_path
        else:
            fp = file_path
        prefix_parts.append(color_path(fp, use_color))

    if show_line_number or (show_column and not show_line_number):
        if show_line_number:
            prefix_parts.append(color_line_number(str(line_num), use_color))

    if show_byte_offset:
        prefix_parts.append(color_line_number(str(byte_offset), use_color))

    if show_column and matches and not is_context:
        col = matches[0][0] + 1
        prefix_parts.append(color_column_number(str(col), use_color))
    elif show_column and is_context:
        pass  # Context lines don't show column

    # Apply trim
    display_line = line
    if trim:
        display_line = line.lstrip()

    # Apply max columns
    max_cols = opts.get('max_columns', None)
    if max_cols is not None and len(display_line) > max_cols:
        if opts.get('max_columns_preview', False):
            display_line = display_line[:max_cols] + ' [... omitted end of long line]'
        else:
            # Omit long lines entirely
            if not is_context:
                line_label = f"[Omitted long matching line]"
                if prefix_parts:
                    line = color_separator(sep, use_color).join(prefix_parts) + color_separator(sep, use_color) + line_label
                else:
                    line = line_label
                return line + '\n'
            return None

    # Apply replacement
    if replacement is not None and not is_context:
        display_line = apply_replacement(display_line, matches, replacement, opts.get('_compiled_re'))

    # Highlight matches in output
    if not is_context and matches and replacement is None and not only_matching:
        if use_color:
            # Build highlighted line
            highlighted = []
            last = 0
            for start, end in matches:
                if trim:
                    # Adjust match positions for trimmed content
                    stripped_len = len(line) - len(line.lstrip())
                    adj_start = start - stripped_len
                    adj_end = end - stripped_len
                    if adj_start < 0:
                        adj_start = 0
                    highlighted.append(re.escape(display_line[last:adj_start]))
                    highlighted.append(color_match(display_line[adj_start:adj_end], True))
                    last = adj_end
                else:
                    highlighted.append(display_line[last:start])
                    highlighted.append(color_match(display_line[start:end], True))
                    last = end
            highlighted.append(display_line[last:])
            display_line = ''.join(highlighted)

    # Build output
    if prefix_parts:
        output_str = color_separator(sep, use_color).join(prefix_parts) + color_separator(sep, use_color) + display_line
    else:
        output_str = display_line

    if only_matching and not is_context:
        lines_out = []
        if matches:
            for start, end in matches:
                match_text = line[start:end]
                if trim:
                    stripped_len = len(line) - len(line.lstrip())
                    s = start - stripped_len
                    e = end - stripped_len
                    if s < 0: s = 0
                    match_text = display_line[max(0, s):max(0, e)]

                if replacement is not None:
                    match_text = apply_replacement(match_text, [(0, len(match_text))], replacement, opts.get('_compiled_re'))

                match_display = color_match(match_text, use_color) if use_color else match_text

                match_prefix_parts = list(prefix_parts)
                if show_column:
                    col = start + 1
                    if match_prefix_parts and show_line_number:
                        # Insert column after line number
                        match_prefix_parts.append(color_column_number(str(col), use_color))
                    elif not show_line_number:
                        match_prefix_parts.append(color_column_number(str(col), use_color))

                if match_prefix_parts:
                    lines_out.append(color_separator(sep, use_color).join(match_prefix_parts) + color_separator(sep, use_color) + match_display)
                else:
                    lines_out.append(match_display)

        return '\n'.join(lines_out) + ('\n' if lines_out else '')

    return output_str + '\n'


