def apply_replacement(line, matches, replacement, compiled_re):
    """Apply a replacement string to a line."""
    # ripgrep uses $0, $1, $2 etc for groups, and ${name} for named groups
    # Convert to Python format

    def replace_func(m):
        result = []
        i = 0
        repl = replacement
        while i < len(repl):
            if repl[i] == '$':
                if i + 1 < len(repl):
                    if repl[i+1] == '{':
                        # ${name} or ${N}
                        j = repl.find('}', i + 2)
                        if j >= 0:
                            name = repl[i+2:j]
                            try:
                                if name.isdigit():
                                    idx = int(name)
                                    if idx == 0:
                                        result.append(m.group(0))
                                    else:
                                        g = m.group(idx)
                                        result.append(g if g is not None else '')
                                else:
                                    g = m.group(name)
                                    result.append(g if g is not None else '')
                            except (IndexError, error):
                                result.append('')
                            i = j + 1
                            continue
                    elif repl[i+1].isdigit():
                        idx = int(repl[i+1])
                        if idx == 0:
                            result.append(m.group(0))
                        else:
                            try:
                                g = m.group(idx)
                                result.append(g if g is not None else '')
                            except IndexError:
                                result.append('')
                        i += 2
                        continue
                    elif repl[i+1] == '$':
                        result.append('$')
                        i += 2
                        continue
                result.append(repl[i])
                i += 1
            else:
                result.append(repl[i])
                i += 1
        return ''.join(result)

    return compiled_re.sub(replace_func, line)


