                matched = fnmatch.fnmatch(basename.lower(), glob.lower())
            else:
                matched = fnmatch.fnmatch(basename, glob)

        if matched:
            if negate:
                result = False
            else:
                result = True

    # If no globs matched at all, check if there are any include globs
    if result is None:
        # Check if there are any non-negate globs
        non_negate = [g for g in include_globs if not g.startswith('!')]
        if non_negate:
            return False  # Didn't match any include glob
        return True  # Only negate globs, file passes

    return result


def _path_glob_match(path, pattern, case_insensitive=False):
    """Match path against a glob pattern with path components."""
    path_parts = path.replace('\\', '/').split('/')
    pattern_parts = pattern.replace('\\', '/').lstrip('/').split('/')

    flags = re.IGNORECASE if case_insensitive else 0

    def match_parts(pp, pattern_p):
        if not pattern_p:
            return len(pp) == 0
        if not pp:
            return all(p == '**' for p in pattern_p)

        if pattern_p[0] == '**':
            # Match zero or more path components
            if match_parts(pp, pattern_p[1:]):
                return True
            if match_parts(pp[1:], pattern_p):
                return True
            return False
        else:
            try:
                rx = re.compile(_glob_part_to_regex(pattern_p[0]) + '$', flags)
                if rx.match(pp[0]):
                    return match_parts(pp[1:], pattern_p[1:])
            except:
                if fnmatch.fnmatch(pp[0].lower() if case_insensitive else pp[0],
                                  pattern_p[0].lower() if case_insensitive else pattern_p[0]):
                    return match_parts(pp[1:], pattern_p[1:])
        return False

    # Try matching from any suffix of path_parts
    for i in range(len(path_parts)):
        if match_parts(path_parts[i:], pattern_parts):
            return True
    return False


def _glob_part_to_regex(part):
    result = []
    i = 0
    while i < len(part):
        c = part[i]
        if c == '*':
            result.append('[^/]*')
        elif c == '?':
            result.append('[^/]')
        elif c == '[':
            j = i + 1
            cls = '['
            if j < len(part) and part[j] in ('!', '^'):
                cls += '^'
                j += 1
            while j < len(part) and part[j] != ']':
                cls += part[j]
                j += 1
            cls += ']'
            result.append(cls)
            i = j + 1
            continue
        else:
            result.append(re.escape(c))
        i += 1
    return ''.join(result)


