            continue

        if os.path.isdir(path):
            if one_file_system:
                try:
                    root_devs.add(os.stat(path).st_dev)
                except:
                    pass

            # Walk the directory
            for root, dirs, files in os.walk(path, followlinks=follow_links):
                # Compute depth
                depth = root[len(path):].count(os.sep)

                # Filter dirs in-place
                dirs_to_remove = []
                for d in dirs[:]:
                    if not hidden and d.startswith('.'):
                        dirs_to_remove.append(d)
                        continue

                    full_dir = os.path.join(root, d)

                    if one_file_system:
                        try:
                            dev = os.stat(full_dir).st_dev
                            if dev not in root_devs:
                                dirs_to_remove.append(d)
                                continue
                        except:
                            pass

                    if ignore_rules and ignore_rules.should_ignore(full_dir, is_dir=True):
                        dirs_to_remove.append(d)
                        continue

                    if max_depth is not None and depth + 1 > max_depth:
                        dirs_to_remove.append(d)
                        continue

                    # Check glob filters for directories
                    if include_globs:
                        # Don't filter dirs by globs, only files
                        pass

                for d in dirs_to_remove:
                    if d in dirs:
                        dirs.remove(d)

                # Sort dirs for consistent ordering? No, use natural order

                # Yield files
                for fname in files:
                    full_path = os.path.join(root, fname)

                    if not hidden and fname.startswith('.'):
                        continue

                    if ignore_rules and ignore_rules.should_ignore(full_path, is_dir=False):
                        continue

                    if max_filesize is not None:
                        try:
                            fsize = os.path.getsize(full_path)
                            if fsize > max_filesize:
                                continue
                        except:
                            pass

                    # Check glob filters
                    if include_globs:
                        if not matches_glob_filters(full_path, include_globs, glob_case_insensitive):
