def format_json_message(msg_type, data):
    """Format a JSON Lines message."""
    return json.dumps({"type": msg_type, "data": data}, ensure_ascii=False)


def search_file(filepath, searcher, opts, stats=None):
    """Search a single file and return formatted results."""
    use_color = opts.get('use_color', False)
    json_output = opts.get('json', False)
    only_matching = opts.get('only_matching', False)
    count_mode = opts.get('count', False)
    count_matches_mode = opts.get('count_matches', False)
    files_with_matches = opts.get('files_with_matches', False)
    files_without_match = opts.get('files_without_match', False)
    passthru = opts.get('passthru', False)
    heading = opts.get('heading', False)
    show_filename = opts.get('show_filename', False)
    before_context = opts.get('before_context', 0)
    after_context = opts.get('after_context', 0)
    vimgrep = opts.get('vimgrep', False)
    quiet = opts.get('quiet', False)
    treat_as_text = opts.get('text', False)
    show_binary = opts.get('binary', False)
    replacement = opts.get('replace', None)
    null_data = opts.get('null_data', False)
    crlf = opts.get('crlf', False)
    encoding = opts.get('encoding', None)
    pre_command = opts.get('pre', None)

    # Read file content
    if filepath == '<stdin>':
        data = sys.stdin.buffer.read()
        path_display = '<stdin>'
    elif pre_command:
        try:
            result = subprocess.run(
                [pre_command, filepath],
                capture_output=True
            )
            data = result.stdout
            path_display = filepath
        except Exception as e:
            if not opts.get('no_messages', False):
                print(f"rg: {filepath}: {e}", file=sys.stderr)
            return False, 0, 0
        path_display = filepath
    else:
        data = read_file_content(filepath)
        path_display = filepath
        if data is None:
            if not opts.get('no_messages', False):
                print(f"rg: {filepath}: No such file or directory (os error 2)", file=sys.stderr)
            return False, 0, 0

    # Check for binary
    is_bin = is_binary(data)

    if is_bin and not treat_as_text and not show_binary:
        # Check if there are any matches
        try:
            content = data.decode('utf-8', errors='replace')
        except:
            content = data.decode('latin-1', errors='replace')

        lines = content.split('\n')
        results = list(searcher.search_lines(lines, path_display))

        if results:
            if json_output:
                pass  # TODO
            else:
                null_offset = data.find(b'\x00')
                print(f"Binary file {path_display} matches (found \"\\0\" byte around offset {null_offset})")
            if stats:
                stats['files_with_match'] += 1
                stats['files_searched'] += 1
            return True, 1, 0
        if stats:
            stats['files_searched'] += 1
        return False, 0, 0

    # Decode content
    try:
        content = decode_content(data, encoding)
    except Exception:
        content = data.decode('latin-1', errors='replace')

    # Handle CRLF
    if crlf:
        content = content.replace('\r\n', '\n')

    # Split into lines
    if null_data:
        lines = content.split('\x00')
        # Remove trailing empty if content ends with null
        if lines and lines[-1] == '':
            lines = lines[:-1]
    else:
        # Keep line endings in check
        lines = content.splitlines()

    if stats:
        stats['files_searched'] += 1
        stats['bytes_searched'] += len(data)

    # Get all results
    all_results = list(searcher.search_lines(lines, path_display))

    has_match = bool(all_results)

    if files_without_match:
        if not has_match:
            if quiet:
                return True, 0, 0
            path_out = path_display
            if opts.get('path_separator'):
                path_out = path_out.replace('/', opts['path_separator'])
            if opts.get('null', False):
                sys.stdout.write(color_path(path_out, use_color) + '\0')
            else:
                print(color_path(path_out, use_color))
        if stats and has_match:
            stats['files_with_match'] += 1
        return has_match, 0, 0

    if not has_match:
        if files_with_matches:
            pass
        if count_mode or count_matches_mode:
            if opts.get('include_zero', False):
                path_out = path_display
                if show_filename:
                    if opts.get('path_separator'):
                        path_out = path_out.replace('/', opts['path_separator'])
                    print(f"{color_path(path_out, use_color)}:0")
        return False, 0, 0

    if stats:
        stats['files_with_match'] += 1

    if files_with_matches:
        if quiet:
            return True, 0, 0
        path_out = path_display
        if opts.get('path_separator'):
            path_out = path_out.replace('/', opts['path_separator'])
        if opts.get('null', False):
            sys.stdout.write(color_path(path_out, use_color) + '\0')
        else:
            print(color_path(path_out, use_color))
        return True, 0, 0

    # Count modes
    if count_mode:
        count = len(all_results)
        if stats:
            stats['matched_lines'] += count
        if quiet:
            return True, count, 0
        path_out = path_display
        if opts.get('path_separator'):
            path_out = path_out.replace('/', opts['path_separator'])
        if show_filename:
            print(f"{color_path(path_out, use_color)}:{count}")
        else:
            print(count)
        return True, count, 0

    if count_matches_mode:
        count = sum(len(r.matches) for r in all_results)
        if stats:
            stats['matches'] += count
        if quiet:
            return True, 0, count
        path_out = path_display
        if opts.get('path_separator'):
            path_out = path_out.replace('/', opts['path_separator'])
        if show_filename:
            print(f"{color_path(path_out, use_color)}:{count}")
        else:
            print(count)
        return True, 0, count

    if quiet:
        return True, 0, 0

    # Build context info
    match_line_nums = {r.line_number for r in all_results}

    # Output results
    output_lines = []

    if json_output:
        # JSON output mode
        path_obj = {"text": path_display}
        begin_msg = format_json_message("begin", {"path": path_obj})
        output_lines.append(begin_msg)

        match_count = 0
        total_bytes_printed = 0

        for r in all_results:
            line_with_nl = r.line_content + '\n'
            submatches = []
            for start, end in r.matches:
                submatches.append({
                    "match": {"text": r.line_content[start:end]},
                    "start": start,
                    "end": end
                })

            match_data = {
                "path": path_obj,
                "lines": {"text": line_with_nl},
                "line_number": r.line_number,
                "absolute_offset": r.byte_offset,
                "submatches": submatches
            }
            msg = format_json_message("match", match_data)
            output_lines.append(msg)
            match_count += 1
            total_bytes_printed += len(msg) + 1

        # End message with stats
        elapsed_secs = 0
        elapsed_nanos = 33000
        end_stats = {
            "elapsed": {"secs": elapsed_secs, "nanos": elapsed_nanos, "human": f"{elapsed_secs + elapsed_nanos/1e9:.6f}s"},
            "searches": 1,
            "searches_with_match": 1 if match_count > 0 else 0,
            "bytes_searched": len(data),
            "bytes_printed": total_bytes_printed,
            "matched_lines": match_count,
            "matches": sum(len(r.matches) for r in all_results)
        }
        end_msg = format_json_message("end", {
            "path": path_obj,
            "binary_offset": None,
            "stats": end_stats
        })
        output_lines.append(end_msg)

        for line in output_lines:
            print(line)

        return True, match_count, 0

    # Heading mode
    if heading:
        path_out = path_display
        if opts.get('path_separator'):
            path_out = path_out.replace('/', opts['path_separator'])
        print(color_path(path_out, use_color))

    context_sep = opts.get('context_separator', '--')

    # Handle context
    if before_context > 0 or after_context > 0:
        _output_with_context(all_results, lines, opts, use_color, path_display, 
                             match_line_nums, before_context, after_context, context_sep)
        if heading:
            print()

        if stats:
            for r in all_results:
                stats['matched_lines'] += 1
                stats['matches'] += len(r.matches)

        return True, len(all_results), 0

    # Simple output without context
    bytes_printed = 0
    for r in all_results:
        if passthru:
            # Output all lines
            pass

        line = r.line_content
        line_num = r.line_number
        matches = r.matches

        if stats:
            stats['matched_lines'] += 1
            stats['matches'] += len(r.matches)

        if vimgrep:
            path_out = path_display
            if opts.get('path_separator'):
                path_out = path_out.replace('/', opts['path_separator'])
            col = matches[0][0] + 1 if matches else 1
            out_line = f"{path_out}:{line_num}:{col}:{line}"
            print(out_line)
            bytes_printed += len(out_line) + 1
            continue

        # Build output line
        parts = []

        sep = opts.get('field_match_separator', ':')

        if show_filename and not heading:
            path_out = path_display
            if opts.get('path_separator'):
                path_out = path_out.replace('/', opts['path_separator'])
            parts.append(color_path(path_out, use_color))

        show_line_number = opts.get('line_number', False)
        if show_line_number:
