def _output_with_context(all_results, lines, opts, use_color, path_display,
                          match_line_nums, before_context, after_context, context_sep):
    """Output results with before/after context."""
    # Build set of lines to show
    to_show = {}  # line_num -> is_match

    for r in all_results:
        ln = r.line_number
        to_show[ln] = ('match', r)

        for i in range(max(1, ln - before_context), ln):
            if i not in to_show:
                to_show[i] = ('context', None)

        for i in range(ln + 1, min(len(lines) + 1, ln + after_context + 1)):
            if i not in to_show:
                to_show[i] = ('context', None)

    sorted_lines = sorted(to_show.keys())

    sep_str = opts.get('context_separator', '--')
    field_match_sep = opts.get('field_match_separator', ':')
    field_context_sep = opts.get('field_context_separator', '-')
    show_filename = opts.get('show_filename', False)
    heading = opts.get('heading', False)
    show_line_number = opts.get('line_number', False)
    show_byte_offset = opts.get('byte_offset', False)
    show_column = opts.get('column', False)
    trim = opts.get('trim', False)

    prev_shown = None

    for ln in sorted_lines:
        if ln < 1 or ln > len(lines):
            continue

        # Check if there's a gap - print separator
        if prev_shown is not None and ln > prev_shown + 1:
            print(color_context_separator(sep_str, use_color))

        line_content = lines[ln - 1]
        kind, result_obj = to_show[ln]

        is_match = (kind == 'match')
        sep = field_match_sep if is_match else field_context_sep

        parts = []

        if show_filename and not heading:
            path_out = path_display
            if opts.get('path_separator'):
                path_out = path_out.replace('/', opts['path_separator'])
            parts.append(color_path(path_out, use_color))

        if show_line_number:
            parts.append(color_line_number(str(ln), use_color))

        if show_byte_offset and result_obj:
            parts.append(color_line_number(str(result_obj.byte_offset), use_color))

        if show_column and is_match and result_obj and result_obj.matches:
            col = result_obj.matches[0][0] + 1
            parts.append(color_column_number(str(col), use_color))

        display_line = line_content
        if trim:
            display_line = line_content.lstrip()

        if is_match and use_color and result_obj and result_obj.matches:
            highlighted = []
            last = 0
            trim_offset = len(line_content) - len(line_content.lstrip()) if trim else 0
            for start, end in result_obj.matches:
                adj_start = start - trim_offset
                adj_end = end - trim_offset
                if adj_start < 0: adj_start = 0
                if adj_end < 0: adj_end = 0
                highlighted.append(display_line[last:adj_start])
                highlighted.append(color_match(display_line[adj_start:adj_end], True))
                last = adj_end
            highlighted.append(display_line[last:])
            display_line = ''.join(highlighted)

        if parts:
            out = color_separator(sep, use_color).join(parts) + color_separator(sep, use_color) + display_line
        else:
            out = display_line

        print(out)
        prev_shown = ln


