                            opts['null'] = True
                            j += 1
                            continue
                    print(f"rg: unrecognized option '-{c}'", file=sys.stderr)
                    print("For more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)

                long_opt = short_to_long[c]

                # Options that take values
                takes_value = long_opt in ('regexp', 'file', 'after-context', 'before-context',
                                           'context', 'replace', 'max-columns', 'max-count',
                                           'max-depth', 'glob', 'type', 'type-not',
                                           'encoding', 'threads', 'sort', 'sortr')

                if takes_value:
                    # Value is rest of this arg or next arg
                    if j + 1 < len(arg):
                        val = arg[j+1:]
                        j = len(arg)  # Consume rest
                    else:
                        i += 1
                        if i >= len(argv):
                            print(f"rg: option '-{c}' requires an argument", file=sys.stderr)
                            sys.exit(2)
                        val = argv[i]
                        j = len(arg)

                    # Process value
                    if long_opt == 'regexp':
                        opts['patterns'].append(val)
                    elif long_opt == 'file':
                        if val == '-':
                            for line in sys.stdin:
                                opts['patterns'].append(line.rstrip('\n').rstrip('\r'))
                        else:
                            try:
                                with open(val, 'r', errors='replace') as fp:
                                    for line in fp:
                                        opts['patterns'].append(line.rstrip('\n').rstrip('\r'))
                            except IOError as e:
                                print(f"rg: {val}: {e}", file=sys.stderr)
                                sys.exit(2)
                    elif long_opt == 'after-context':
                        opts['after_context'] = int(val)
                    elif long_opt == 'before-context':
                        opts['before_context'] = int(val)
                    elif long_opt == 'context':
                        v = int(val)
                        opts['before_context'] = v
                        opts['after_context'] = v
                    elif long_opt == 'replace':
                        opts['replace'] = val
                    elif long_opt == 'max-columns':
                        opts['max_columns'] = int(val)
                    elif long_opt == 'max-count':
                        opts['max_count'] = int(val)
                    elif long_opt == 'max-depth':
                        opts['max_depth'] = int(val)
                    elif long_opt == 'glob':
                        opts['globs'].append(val)
                    elif long_opt == 'type':
                        opts['type_includes'].append(val)
                    elif long_opt == 'type-not':
                        opts['type_excludes'].append(val)
                    elif long_opt == 'encoding':
                        opts['encoding'] = val
                    elif long_opt == 'threads':
                        opts['threads'] = int(val)
                    elif long_opt == 'sort':
                        opts['sort'] = val
                    elif long_opt == 'sortr':
                        opts['sortr'] = val
                else:
                    # Boolean flag
                    if long_opt == 'ignore-case':
                        opts['ignore_case'] = True
                    elif long_opt == 'case-sensitive':
                        opts['case_sensitive'] = True
                        opts['ignore_case'] = False
                        opts['smart_case'] = False
                    elif long_opt == 'smart-case':
                        opts['smart_case'] = True
                    elif long_opt == 'fixed-strings':
                        opts['fixed_strings'] = True
                    elif long_opt == 'invert-match':
                        opts['invert_match'] = True
                    elif long_opt == 'word-regexp':
                        opts['word_regexp'] = True
                    elif long_opt == 'line-regexp':
                        opts['line_regexp'] = True
                    elif long_opt == 'multiline':
                        opts['multiline'] = True
                    elif long_opt == 'pcre2':
                        opts['pcre2'] = True
                    elif long_opt == 'line-number':
                        opts['line_number'] = True
                    elif long_opt == 'no-line-number':
                        opts['line_number'] = False
                        opts['no_line_number'] = True
                    elif long_opt == 'count':
                        opts['count'] = True
                    elif long_opt == 'files-with-matches':
                        opts['files_with_matches'] = True
                    elif long_opt == 'follow':
                        opts['follow'] = True
                    elif long_opt == 'hidden':
                        opts['hidden'] = True
                    elif long_opt == 'text':
                        opts['text'] = True
                    elif long_opt == 'byte-offset':
                        opts['byte_offset'] = True
                    elif long_opt == 'with-filename':
                        opts['with_filename'] = True
                    elif long_opt == 'no-filename':
                        opts['no_filename'] = True
                        opts['with_filename'] = False
                    elif long_opt == 'only-matching':
                        opts['only_matching'] = True
                    elif long_opt == 'quiet':
                        opts['quiet'] = True
                    elif long_opt == 'pretty':
                        opts['pretty'] = True
                    elif long_opt == 'version':
                        opts['version'] = True
                    elif long_opt == 'help':
                        opts['help_short'] = True
                    elif long_opt == 'unrestricted':
                        opts['_unrestricted_count'] = opts.get('_unrestricted_count', 0) + 1
                    elif long_opt == 'null':
                        opts['null'] = True
                    elif long_opt == 'search-zip':
                        opts['search_zip'] = True

                j += 1

        else:
            positional.append(arg)

        i += 1

    # Process positional args
    # If patterns were given via -e or -f, all positional are paths
    if opts['patterns']:
        opts['paths'] = positional
    else:
        if positional:
            opts['patterns'] = [positional[0]]
            opts['paths'] = positional[1:]
        else:
            opts['paths'] = []

    return opts


