def main():
    """Main entry point."""
    argv = sys.argv[1:]

    # Load config file first (unless --no-config is in argv)
    no_config = '--no-config' in argv
    if not no_config:
        config_args = load_config_file()
        # Config args come first, command line overrides
        argv = config_args + argv

    # Parse args
    opts = parse_args(argv)

    # Apply --pretty (-p) flag
    if opts['pretty']:
        if opts['color'] == 'auto':
            opts['color'] = 'always'
        if opts['heading'] is None:
            opts['heading'] = True
        if opts['line_number'] is None:
            opts['line_number'] = True

    # Apply -u (unrestricted) flag
    unrestricted = opts.get('_unrestricted_count', 0)
    if unrestricted >= 1:
        opts['no_ignore'] = True
    if unrestricted >= 2:
        opts['hidden'] = True
    if unrestricted >= 3:
        opts['text'] = True

    # Handle special commands
    if opts['version']:
        print(f"ripgrep {VERSION} (rev {REV})")
        print()
        print("features:-pcre2")
        print("simd(compile):+SSE2,-SSSE3,-AVX2")
        print("simd(runtime):+SSE2,+SSSE3,+AVX2")
        print()
        print("PCRE2 is not available in this build of ripgrep.")
        return 0

    if opts['pcre2_version']:
        print("PCRE2 is not available in this build of ripgrep.", file=sys.stderr)
        return 2

    if opts.get('help'):
        print(HELP_LONG_TEXT, end='')
        return 0

    if opts.get('help_short'):
        print(HELP_SHORT_TEXT, end='')
        return 0

    if opts['generate']:
        kind = opts['generate']
        if kind == 'complete-bash':
            print(COMPLETE_BASH, end='')
        elif kind == 'complete-zsh':
            print(COMPLETE_ZSH, end='')
        elif kind == 'complete-fish':
            print(COMPLETE_FISH, end='')
        elif kind == 'complete-powershell':
            print(COMPLETE_POWERSHELL, end='')
        elif kind == 'man':
            print(MAN_TEXT, end='')
        else:
            print(f"rg: unknown generate kind: {kind}", file=sys.stderr)
            return 2
        return 0

    if opts['type_list']:
        # Apply type-add and type-clear
        file_types_extra = apply_type_modifications(opts)
        all_types = dict(FILE_TYPES)
        all_types.update(file_types_extra)
        for type_name in sorted(all_types.keys()):
            globs = all_types[type_name]
            print(f"{type_name}: {', '.join(globs)}")
        return 0

    # Determine output settings
    output_is_tty = sys.stdout.isatty()
    use_color = should_use_color(opts['color'], output_is_tty)

    # Files mode
    if opts['files']:
        paths = opts['paths'] if opts['paths'] else ['.']

        # Setup ignore rules
        ignore_rules = setup_ignore_rules(opts)
        opts['_ignore_rules'] = ignore_rules

        # Apply type modifications
        opts['_file_types_extra'] = apply_type_modifications(opts)

        file_list = list(walk_files(paths, opts))

        # Sort if requested
        if opts['sort']:
            file_list = sort_files(file_list, opts['sort'])
        elif opts['sortr']:
            file_list = sort_files(file_list, opts['sortr'], reverse=True)

        for fp in file_list:
            path_out = fp
            if opts.get('path_separator'):
                path_out = path_out.replace('/', opts['path_separator'])
            if opts.get('null', False):
                sys.stdout.write(color_path(path_out, use_color) + '\0')
            else:
                print(color_path(path_out, use_color))
        return 0

    # Check that patterns are provided
    if not opts['patterns']:
        print("rg: ripgrep requires at least one pattern to execute a search", file=sys.stderr)
        print("For more information, try '--help'.", file=sys.stderr)
        return 2

    # Apply type modifications
    opts['_file_types_extra'] = apply_type_modifications(opts)

    # Validate patterns
    for p in opts['patterns']:
        if not opts['fixed_strings']:
            err = validate_pattern(p)
            if err:
                print(err, file=sys.stderr)
                return 2

    # Setup ignore rules
    ignore_rules = setup_ignore_rules(opts)
    opts['_ignore_rules'] = ignore_rules

    # Determine search mode
    paths = opts['paths']
    stdin_mode = False

    if not paths:
        # Check if stdin is a tty
        if sys.stdin.isatty():
            # Search current directory
            paths = ['.']
        else:
            # Search stdin
            stdin_mode = True

    # Determine if we should show filenames
    show_filename = opts.get('with_filename')
    if opts.get('no_filename'):
        show_filename = False
    elif show_filename is None:
        # Auto-detect: show filename if multiple files/dirs or single dir
        if stdin_mode:
            show_filename = False
        elif len(paths) == 1 and os.path.isfile(paths[0]):
            show_filename = False
        else:
            show_filename = True

    opts['show_filename'] = show_filename
    opts['use_color'] = use_color

    # Determine heading default
    if opts['heading'] is None:
        if output_is_tty:
            opts['heading'] = True
        else:
            opts['heading'] = False

    # Determine line number default
    if opts['line_number'] is None:
        if output_is_tty and not opts['count'] and not opts['count_matches'] and not opts['files_with_matches']:
            opts['line_number'] = True
        else:
            opts['line_number'] = False

    # If --column is set, also enable line numbers
    if opts['column']:
        if opts['line_number'] is None:
            opts['line_number'] = True

    # --vimgrep implies line numbers and column numbers
    if opts['vimgrep']:
        opts['line_number'] = True
        opts['column'] = True
        opts['show_filename'] = True
        opts['heading'] = False

    # Create searcher
    searcher = Searcher(opts['patterns'], opts)

    if searcher.error:
        print(searcher.error, file=sys.stderr)
        return 2

    opts['_compiled_re'] = searcher.compiled_re

    # Stats
    stats_data = None
    if opts['stats'] or opts['json']:
        stats_data = {
            'matched_lines': 0,
            'matches': 0,
            'files_with_match': 0,
            'files_searched': 0,
            'bytes_searched': 0,
            'bytes_printed': 0,
        }

    start_time = time.time()

    # Get list of files to search
    if stdin_mode:
        files_to_search = ['<stdin>']
    else:
        files_to_search = list(walk_files(paths, opts))

        # Sort if requested
        if opts['sort']:
            files_to_search = sort_files(files_to_search, opts['sort'])
        elif opts['sortr']:
            files_to_search = sort_files(files_to_search, opts['sortr'], reverse=True)

    # JSON output stats accumulation
    json_total_bytes_printed = 0

    # Search each file
    found_match = False
    for fp in files_to_search:
        has_match, mlines, mcount = search_file(fp, searcher, opts, stats_data)
        if has_match:
            found_match = True
            if opts['quiet'] and not opts['stats']:
                break

    end_time = time.time()
    elapsed = end_time - start_time

    # Print stats
    if opts['stats'] and not opts['files_with_matches'] and not opts['files_without_match']:
        if stats_data:
            matched_lines = stats_data['matched_lines']
            files_with_match = stats_data['files_with_match']
            files_searched = stats_data['files_searched']
            bytes_printed = stats_data['bytes_printed']
            bytes_searched = stats_data['bytes_searched']

            print()
            print(f"{matched_lines} matches")
            print(f"{matched_lines} matched lines")
            print(f"{files_with_match} files contained matches")
            print(f"{files_searched} files searched")
            print(f"{bytes_printed} bytes printed")
            print(f"{bytes_searched} bytes searched")
            print(f"{elapsed:.6f} seconds spent searching")
            print(f"{elapsed:.6f} seconds")

    # JSON summary
    if opts['json']:
        elapsed_nanos = int(elapsed * 1e9)
        elapsed_secs = int(elapsed)
        elapsed_human = f"{elapsed:.6f}s"

        if stats_data:
            summary_stats = {
                "bytes_printed": stats_data['bytes_printed'],
                "bytes_searched": stats_data['bytes_searched'],
                "elapsed": {
                    "human": elapsed_human,
                    "nanos": elapsed_nanos,
                    "secs": elapsed_secs
                },
                "matched_lines": stats_data['matched_lines'],
                "matches": stats_data.get('matches', stats_data['matched_lines']),
                "searches": stats_data['files_searched'],
                "searches_with_match": stats_data['files_with_match']
            }
            summary = {
                "data": {
                    "elapsed_total": {
                        "human": elapsed_human,
                        "nanos": elapsed_nanos,
                        "secs": elapsed_secs
                    },
                    "stats": summary_stats
                },
                "type": "summary"
            }
            print(json.dumps(summary, ensure_ascii=False))

    return 0 if found_match else 1


def validate_pattern(pattern):
    """Validate a pattern and return error message if invalid."""
    # Check for unsupported features
    searcher = Searcher([pattern], {'fixed_strings': False})
    if searcher.error:
        return searcher.error
    return None


def apply_type_modifications(opts):
    """Apply --type-add and --type-clear modifications."""
    extra = {}

    # Process type-clear
    for type_name in opts.get('type_clear', []):
        extra[type_name] = []

    # Process type-add
    for spec in opts.get('type_add', []):
        if ':' in spec:
            type_name, globs_str = spec.split(':', 1)
            globs = [g.strip() for g in globs_str.split(',')]
            if type_name in extra:
                extra[type_name].extend(globs)
            else:
                extra[type_name] = globs

    return extra


def setup_ignore_rules(opts):
    """Setup ignore rules from options."""
    return IgnoreRules(
        require_git=not opts.get('no_require_git', False),
        no_ignore=opts.get('no_ignore', False),
        no_ignore_dot=opts.get('no_ignore_dot', False),
        no_ignore_vcs=opts.get('no_ignore_vcs', False),
        no_ignore_global=opts.get('no_ignore_global', False),
        no_ignore_parent=opts.get('no_ignore_parent', False),
        extra_ignore_files=opts.get('ignore_files', []),
        ignore_file_case_insensitive=opts.get('ignore_file_case_insensitive', False),
    )


def sort_files(files, sort_key, reverse=False):
    """Sort file list by the given key."""
    if sort_key in ('path', 'none'):
        return sorted(files, reverse=reverse)
    elif sort_key == 'modified':
        try:
            return sorted(files, key=lambda f: os.path.getmtime(f), reverse=reverse)
        except:
            return sorted(files, reverse=reverse)
    elif sort_key == 'created':
        try:
            return sorted(files, key=lambda f: os.path.getctime(f), reverse=reverse)
        except:
            return sorted(files, reverse=reverse)
    elif sort_key == 'accessed':
        try:
            return sorted(files, key=lambda f: os.path.getatime(f), reverse=reverse)
        except:
            return sorted(files, reverse=reverse)
    else:
        return sorted(files, reverse=reverse)


